class SafariState
  attr_accessor :ballcount
  attr_accessor :captures
  attr_accessor :decision
  attr_accessor :steps

  def initialize
    @start      = nil
    @ballcount  = 0
    @captures   = 0
    @inProgress = false
    @steps      = 0
    @decision   = 0
  end

  def pbReceptionMap
    return @inProgress ? @start[0] : 0
  end

  def inProgress?
    return @inProgress
  end

  def pbGoToStart
    if $scene.is_a?(Scene_Map)
      pbFadeOutIn do
        $game_temp.player_transferring   = true
        $game_temp.transition_processing = true
        $game_temp.player_new_map_id    = @start[0]
        $game_temp.player_new_x         = @start[1]
        $game_temp.player_new_y         = @start[2]
        $game_temp.player_new_direction = 2
        pbDismountBike
        $scene.transfer_player
      end
    end
  end

  def pbStart(ballcount)
    @start      = [$game_map.map_id, $game_player.x, $game_player.y, $game_player.direction]
    @ballcount  = ballcount
    @inProgress = true
    @steps      = Settings::SAFARI_STEPS
  end

  def pbEnd
    @start      = nil
    @ballcount  = 0
    @captures   = 0
    @inProgress = false
    @steps      = 0
    @decision   = 0
    $game_map.need_refresh = true
  end
end

def clear
  @ballcount    = 0
  @ended        = false
  @inProgress   = false
  @decision     = 0
  @lastPokemon  = nil
  @otherparty   = []
  @contestants  = []
  @places       = []
  @start        = nil
  @contestMaps  = []
  @reception    = []
end

def pbStart(ballcount)
  @ballcount = ballcount
  @inProgress = true
  @otherparty = []
  @lastPokemon = nil
  @lastContest = nil
  @timer_start = System.uptime
  @places = []
  chosenpkmn = $player.party[@chosenPokemon]
  $player.party.length.times do |i|
    @otherparty.push($player.party[i]) if i != @chosenPokemon
  end
  @contestants = []
  [5, CONTESTANT_NAMES.length].min.times do
    loop do
      value = rand(CONTESTANT_NAMES.length)
      next if @contestants.include?(value)
      @contestants.push(value)
      break
    end
  end
  $player.party = [chosenpkmn]
  @decision = 0
  @ended = false
  $stats.bug_contest_count += 1
end

def pbEnd(interrupted = false)
  return if !@inProgress
  @otherparty.each { |pkmn| $player.party.push(pkmn) }
  if interrupted
    @ended = false
  else
    pbNicknameAndStore(@lastPokemon) if @lastPokemon
    @ended = true
  end
  $stats.bug_contest_wins += 1 if place == 0
  @ballcount = 0
  @inProgress = false
  @decision = 0
  @lastPokemon = nil
  @otherparty = []
  @contestMaps = []
  @reception = []
  @lastContest = pbGetTimeNow.to_i
  $game_map.need_refresh = true
end
